"""
Bundled canonical BCD templates for standalone recovery.
"""
import base64
import gzip

_UEFI_BCD_GZ_B64 = ""
_PCAT_BCD_GZ_B64 = ""

def get_uefi_bcd_template() -> bytes:
    """Return raw bytes for canonical UEFI BCD hive."""
    return gzip.decompress(base64.b64decode(_UEFI_BCD_GZ_B64))

def get_pcat_bcd_template() -> bytes:
    """Return raw bytes for canonical PCAT/BIOS BCD hive."""
    return gzip.decompress(base64.b64decode(_PCAT_BCD_GZ_B64))
